    demoGuestRestoredRef.current = true;
    commitDocumentSnapshot({
      ...guestDoc,
      elements: restoredElements,
      deletedElements: Array.isArray(guestDoc.deletedIds) ? guestDoc.deletedIds : [],
      title: guestDoc.title || "",
      cvData: guestDoc.cvData ?? null,
      sourceImportId: null,
      pdfId: null,
      revision: null,
      isDemoContent: true,
    }, { markClean: true });
